<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>ScreenVault — 400,000+ UI Screenshots for Designers</title>
  <meta name="description" content="ScreenVault is a massive UI/UX inspiration library with 615,900 screens, 329,200 flows, and workflow-ready tools for product teams." />
  <style>
    :root {
      --bg: oklch(98.5% 0.006 255);
      --surface: oklch(100% 0 0);
      --surface-2: oklch(96.8% 0.008 255);
      --text: oklch(20% 0.02 260);
      --muted: oklch(46% 0.02 260);
      --line: oklch(89% 0.01 255);
      --accent: oklch(58% 0.23 262);
      --accent-strong: oklch(51% 0.25 262);
      --accent-soft: oklch(95% 0.025 262);
      --shadow: 0 8px 30px oklch(20% 0.02 260 / 0.06);
      --radius: 16px;
      --ease: cubic-bezier(.2,.8,.2,1);
    }

    * { box-sizing: border-box; }
    html, body { margin: 0; padding: 0; }
    body {
      font-family: Inter, "General Sans", "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      color: var(--text);
