      line-height: 1.45;
    }
    a { color: inherit; text-decoration: none; }

    .container { width: min(1140px, calc(100% - 2rem)); margin-inline: auto; }
    .section { padding: 4.5rem 0; }
    .section-head { text-align: center; max-width: 700px; margin: 0 auto 2rem; }
