    p.lead { margin-top: .9rem; font-size: clamp(1rem, 1.8vw, 1.2rem); color: var(--muted); }

    .announcement {
      background: var(--surface);
      border-bottom: 1px solid var(--line);
      font-size: .88rem;
    }
    .announcement .container {
      padding: .65rem 0;
      display: flex; justify-content: center; gap: .5rem; align-items: center;
    }
    .pill {
      background: var(--accent-soft); color: var(--accent-strong);
      border: 1px solid oklch(90% 0.03 262);
      border-radius: 999px; padding: .2rem .6rem; font-weight: 600; font-size: .75rem;
    }

    header {
      position: sticky; top: 0; z-index: 50;
      backdrop-filter: blur(10px);
      background: oklch(98.5% 0.006 255 / .85);
