    }
    .nav { height: 74px; display: flex; justify-content: space-between; align-items: center; gap: 1rem; }
    .logo { display: flex; align-items: center; gap: .65rem; font-weight: 700; letter-spacing: -.01em; }
    .logo-mark {
      width: 32px; height: 32px; border-radius: 10px;
