    .tab.active { background: var(--accent-soft); color: var(--accent-strong); border-color: oklch(90% 0.03 262); }

    .filters { display: flex; gap: .5rem; padding: .9rem; flex-wrap: wrap; border-bottom: 1px solid var(--line); }
    .filter {
      border: 1px solid var(--line); border-radius: 999px; padding: .38rem .72rem; font-size: .84rem;
