    .results { padding: 1rem; display: grid; grid-template-columns: repeat(4, minmax(0,1fr)); gap: .65rem; min-height: 260px; }
    .result-card {
      min-height: 120px; background: linear-gradient(180deg, oklch(98% 0.006 255), oklch(93.5% 0.012 255));
