      transition: transform 220ms var(--ease), box-shadow 220ms var(--ease);
    }
    .result-card:hover { transform: translateY(-2px); box-shadow: 0 10px 20px oklch(20% 0.02 260 / .09); }
    .result-tag { font-size: .72rem; color: var(--muted); }

    .flows-card {
      margin-top: 1rem;
      background: var(--surface); border: 1px solid var(--line); border-radius: calc(var(--radius) + 4px); padding: 1rem;
    }
    .toggle { display: inline-flex; border: 1px solid var(--line); border-radius: 12px; padding: .2rem; background: var(--surface-2); gap: .2rem; }
    .toggle button { border: 0; background: transparent; padding: .48rem .78rem; border-radius: 10px; font-weight: 600; color: var(--muted); cursor: pointer; }
    .toggle button.active { background: var(--surface); color: var(--text); box-shadow: 0 2px 8px oklch(20% 0.02 260 / .08); }
    .flow-pane { margin-top: .9rem; min-height: 180px; border: 1px dashed var(--line); border-radius: 14px; padding: 1rem; }
    .steps { display: grid; grid-template-columns: repeat(4, 1fr); gap: .6rem; }
    .step, .video {
      border: 1px solid var(--line); border-radius: 12px; background: var(--surface);
      min-height: 110px; padding: .65rem;
    }

    .tools-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: .9rem; }
    .tool-card { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); padding: 1.1rem; }
