    .tool-card p { color: var(--muted); margin-top: .45rem; }

    .marquee-wrap { overflow: hidden; }
    .marquee-row { display: flex; width: max-content; gap: .8rem; margin-bottom: .8rem; animation: marquee 32s linear infinite; }
    .marquee-row.rev { animation-direction: reverse; }
    .t-card {
      width: 290px; background: var(--surface); border: 1px solid var(--line); border-radius: 14px;
      padding: 1rem; box-shadow: 0 6px 18px oklch(20% 0.02 260 / .05);
