    .t-name { font-weight: 700; font-size: .92rem; margin-top: .5rem; }
    .t-role { font-size: .78rem; color: var(--muted); }

    .cta {
      border: 1px solid var(--line); border-radius: calc(var(--radius) + 8px);
      background: linear-gradient(180deg, var(--surface), oklch(96.2% 0.01 255));
      padding: 2rem 1rem;
      text-align: center;
    }
    .icon-marquee { overflow: hidden; margin-top: 1.3rem; }
    .icon-track { display: flex; width: max-content; gap: .55rem; animation: marquee 26s linear infinite; }
    .icon-track.rev { animation-direction: reverse; }
    .icon {
      width: 54px; height: 54px; border-radius: 14px; border: 1px solid var(--line); background: var(--surface);
      display: grid; place-items: center; font-size: 1.2rem;
    }

    footer { padding: 2.2rem 0 3rem; color: var(--muted); font-size: .9rem; }
    .foot { display: flex; justify-content: space-between; gap: 1rem; flex-wrap: wrap; border-top: 1px solid var(--line); padding-top: 1rem; }

    @keyframes marquee { from { transform: translateX(0); } to { transform: translateX(-50%); } }

    @media (max-width: 980px) {
      .hero-grid { grid-template-columns: 1fr; }
      .results { grid-template-columns: repeat(3, 1fr); }
      .tools-grid, .stats-grid { grid-template-columns: 1fr 1fr; }
      .logo-row { grid-template-columns: repeat(3, 1fr); }
      .steps { grid-template-columns: repeat(2, 1fr); }
    }

    @media (max-width: 700px) {
      .section { padding: 3.4rem 0; }
      .nav-links { display: none; }
      .results { grid-template-columns: repeat(2, 1fr); }
      .tools-grid, .stats-grid { grid-template-columns: 1fr; }
      .logo-row { grid-template-columns: repeat(2, 1fr); }
      .t-card { width: 250px; }
      .icon { width: 46px; height: 46px; border-radius: 12px; }
    }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after { animation: none !important; transition: none !important; }
    }
  </style>
</head>
