  <div class="announcement" id="announcement-bar">
    <div class="container"><span class="pill">New</span> ScreenVault now includes 329,200 curated user flows.</div>
  </div>

  <header>
    <div class="container nav">
      <div class="logo"><span class="logo-mark"></span>ScreenVault</div>
