  <script>
    const featureTabs = ["Screens", "UI Elements", "Flows", "Text in Screenshot"];
    const categories = ["Profile", "Wallet", "Welcome", "Account Setup", "Home", "Subscription & Paywall", "Login", "Settings", "Checkout", "Collections"];

    const testimonialData = [
      { name: "Sebastian Speier", role: "Principal Product Designer", quote: "ScreenVault turned our benchmark phase from hours into minutes." },
      { name: "Meng To", role: "Design Founder", quote: "The depth is wild — I keep finding patterns I’d never noticed." },
      { name: "Marco Cornacchia", role: "Staff Product Designer", quote: "Best place to align teams quickly on visual direction." },
      { name: "Daryl Ginn", role: "Design Lead", quote: "Search + flows is the killer combo for real product work." },
      { name: "Rachel How", role: "Product Design Manager", quote: "Our designers use this every sprint planning cycle." },
      { name: "Haerin Song", role: "Senior Product Designer", quote: "Feels like a design copilot for interface decisions." }
    ];

    const tabsEl = document.querySelector('.tabs');
    const filtersEl = document.querySelector('.filters');
    const resultsEl = document.getElementById('results-grid');

    let activeTab = featureTabs[0];
    let activeFilter = categories[0];

    function renderTabs() {
      tabsEl.innerHTML = "";
      featureTabs.forEach(tab => {
        const button = document.createElement('button');
        button.className = `tab ${tab === activeTab ? 'active' : ''}`;
        button.textContent = tab;
        button.addEventListener('click', () => {
          activeTab = tab;
          renderTabs();
          renderResults();
        });
        tabsEl.appendChild(button);
      });
    }

    function renderFilters() {
      filtersEl.innerHTML = "";
      categories.forEach(filter => {
        const button = document.createElement('button');
        button.className = `filter ${filter === activeFilter ? 'active' : ''}`;
        button.textContent = filter;
        button.addEventListener('click', () => {
          activeFilter = filter;
          renderFilters();
          renderResults();
        });
        filtersEl.appendChild(button);
      });
    }

    function renderResults() {
      const tabSeed = featureTabs.indexOf(activeTab) + 2;
      const catSeed = categories.indexOf(activeFilter) + 3;
      resultsEl.innerHTML = "";
      for (let i = 0; i < 8; i++) {
        const card = document.createElement('article');
        card.className = 'result-card';
        const scale = ((i + tabSeed + catSeed) % 4) + 1;
        card.innerHTML = `<div class="result-tag">${activeTab} • ${activeFilter}</div>
          <div style="margin-top:.6rem;height:${62 + scale * 12}px;border-radius:9px;background:linear-gradient(180deg, oklch(95% 0.012 ${245 + scale * 4}), oklch(89% 0.02 ${255 + scale * 5}));border:1px solid var(--line)"></div>`;
        resultsEl.appendChild(card);
      }
    }

    function animateCount(element, target, duration = 1300, delay = 0) {
      const start = 0;
      const startTime = performance.now() + delay;
      function update(now) {
        if (now < startTime) return requestAnimationFrame(update);
        const t = Math.min((now - startTime) / duration, 1);
        const eased = 1 - Math.pow(1 - t, 3);
        const value = Math.floor(start + (target - start) * eased);
        element.textContent = value.toLocaleString();
        if (t < 1) requestAnimationFrame(update);
      }
      requestAnimationFrame(update);
    }

    function setupStatsCounter() {
      const statNums = [...document.querySelectorAll('.stat-num')];
      let hasRun = false;
      const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
          if (entry.isIntersecting && !hasRun) {
            hasRun = true;
            statNums.forEach((el, idx) => animateCount(el, Number(el.dataset.target), 1300 + idx * 160, idx * 120));
            observer.disconnect();
          }
        });
      }, { threshold: 0.35 });
      observer.observe(document.getElementById('stats'));
    }

    function setupFlowToggle() {
      const pane = document.getElementById('flow-pane');
      const buttons = [...document.querySelectorAll('.toggle button')];

      function render(mode) {
        if (mode === 'videos') {
          pane.innerHTML = `<div class="video"><strong>Flow video timeline</strong><p style="color:var(--muted)">Watch real user journeys across onboarding, activation, and upgrade paths.</p></div>`;
        } else {
          pane.innerHTML = `<div class="steps">
            <div class="step"><strong>Step 1</strong><p style="color:var(--muted)">Welcome</p></div>
            <div class="step"><strong>Step 2</strong><p style="color:var(--muted)">Permissions</p></div>
            <div class="step"><strong>Step 3</strong><p style="color:var(--muted)">Personalization</p></div>
            <div class="step"><strong>Step 4</strong><p style="color:var(--muted)">Home state</p></div>
          </div>`;
        }
      }

      buttons.forEach(btn => {
        btn.addEventListener('click', () => {
          buttons.forEach(b => b.classList.remove('active'));
          btn.classList.add('active');
          render(btn.dataset.mode);
        });
      });
      render('videos');
    }

    function createTestimonialCard(item) {
      return `<article class="t-card"><p>“${item.quote}”</p><div class="t-name">${item.name}</div><div class="t-role">${item.role}</div></article>`;
    }

    function fillMarqueeRows() {
      const rowA = document.getElementById('row-a');
      const rowB = document.getElementById('row-b');
      const doubled = [...testimonialData, ...testimonialData];
      rowA.innerHTML = doubled.map(createTestimonialCard).join('');
      rowB.innerHTML = [...doubled].reverse().map(createTestimonialCard).join('');
    }

    function fillIconMarquees() {
      const icons = ["🎨","📱","🧠","🧩","📝","⚡","📊","🛒","🔒","💳","👋","🔍"];
      const trackA = document.getElementById('icons-1');
      const trackB = document.getElementById('icons-2');
      const doubled = [...icons, ...icons, ...icons];
      trackA.innerHTML = doubled.map(i => `<div class="icon">${i}</div>`).join('');
      trackB.innerHTML = [...doubled].reverse().map(i => `<div class="icon">${i}</div>`).join('');
    }

    renderTabs();
    renderFilters();
    renderResults();
    setupStatsCounter();
    setupFlowToggle();
    fillMarqueeRows();
    fillIconMarquees();
  </script>
</body>
